Consider a moment-based ambiguity set ``centered'' at the nominal distribution $\widehat \mathbb{P}$ with radius $ \rho>0$:
\begin{equation} \label{eq:ambiguity}
    \mathcal{P}_ \rho(\widehat{\mathbb{P}}) \triangleq \left\{\mathbb{Q}: \mathbb{E}_{\mathbb{Q}}[\xi] = 0, \mathbb{E}_{\mathbb{Q}}[\xi\xi^\top] = S, D\left(S, \mathbb{E}_{\widehat{\mathbb{P}}}[\xi\xi^\top]\right)\leq  \rho\right\}.
\end{equation}

To robustify the empirical model~\eqref{prob:jointly-estimate-model} against all potential mismatches against distributions in $\mathcal{P}_\rho (\widehat{\mathbb{P}})$, we define the pair of distributionally robust covariance-precision matrix estimators $(\Sigma^\star, X^\star)$ as the solution of a min-max problem
\begin{equation}
    (\Sigma^\star, X^\star) \triangleq \arg\min\limits_{\substack{\Sigma,X \in {\mathbb{S}^p_{++}} \\ X \Sigma = I}}\;\max\limits_{\mathbb{Q}\in \mathcal{P}_ \rho(\widehat{\mathbb{P}})}  -\log\det X+\mathbb{E}_{{\mathbb{Q}}}[\langle X,\xi\xi^\top\rangle] +\frac{1}{2}\tau \left(\|\Sigma\|_F^2-2\mathbb{E}_{{\mathbb{Q}}}[\langle \Sigma, \xi \xi^\top\rangle]\right). \tag{DRO}
    \label{prob:jointly-model-dro}
\end{equation}

\begin{equation}\label{prob:robust-model}
    \displaystyle (\Sigma^\star, X^\star) = \arg\min_{\substack{\Sigma,X \in {\mathbb{S}^p_{++}} \\ X \Sigma = I}} ~\max\limits_{S \in {\mathbb{S}^p_{+}}: D(S, \widehat{\Sigma})\leq  \rho}~\left\{ f(\Sigma, X, S) \triangleq -\log\det X+\langle X,S\rangle +\frac{1}{2}\tau \left(\|\Sigma\|_F^2-2\langle \Sigma, S\rangle\right) \right\}. \tag{RO}
\end{equation}

\begin{equation}\label{prob:robust-model-X}
        \displaystyle \min_{X \in {\mathbb{S}^p_{++}}} ~\max\limits_{S \in {\mathbb{S}^p_{+}}: D(S, \widehat{\Sigma})\leq  \rho}~\left\{ f_1(X, S) \triangleq -\log\det X+\langle X,S\rangle +\frac{1}{2}\tau \left(\|X^{-1}\|_F^2 - 2\langle X^{-1}, S\rangle\right) \right\}.
    \end{equation}

The following theorem states that under these assumptions, the optimal solution to~\eqref{prob:robust-model} can be
derived by the optimal solution to the following convex optimization problem:
\begin{align}\tag{P-Mat}\label{prob:P-Mat}
\max_{\Sigma\in{\mathbb{S}^p_{++}}: D(\Sigma, \widehat{\Sigma})\leq  \rho}~ \log\det \Sigma - \frac{1}{2}\tau \|\Sigma\|_F^2.
\end{align}

\label{thm:convex-reform}
    Let Assumptions~\ref{ass:regularity-nominal} and~\ref{ass:convex-divergence} hold. Then
    \begin{enumerate}[label=(\roman*)]
        \item \eqref{prob:P-Mat} admits a unique optimal solution $\Sigma^\star$,
        \item \eqref{prob:robust-model} admits a unique optimal solution pair, which can be represented $(\Sigma=\Sigma^\star, X=(\Sigma^\star)^{-1})$.
    \end{enumerate}

\label{prop:unbinding}
   Let  $\rho$ be such that
   $D\left(\sqrt{\frac{1}{\tau}} I, \widehat \Sigma \right)\leq  \rho$. Then $\Sigma^\star=\sqrt{\frac{1}{\tau}} I$ is the optimal solution to~\eqref{prob:P-Mat}.

The construction involves a eigenvalue mapping corresponding to the generator $d$ of the divergence function, which is defined by
\begin{align}\label{eq:def-varphi}
\varphi(\tau, \gamma, b) \triangleq \text{the unique solution $a^\star> 0$ of the equation } 0 = \frac{1}{a^\star}-\tau a^\star -\gamma \frac{\partial d}{\partial a} (a^\star, b).
\end{align}

\begin{align}\label{eq:def-varphi}
\varphi(\tau, \gamma, b) \triangleq \text{the unique solution $a^\star> 0$ of the equation } 0 = \frac{1}{a^\star}-\tau a^\star -\gamma \frac{\partial d}{\partial a} (a^\star, b).
\end{align}

\label{thm:close-form-dro}
    Under Assumptions~\ref{ass:regularity-nominal}-\ref{ass:reg-radius},  the optimal solution to~\eqref{prob:robust-model} is 
    \begin{eqnarray} 
    \label{eq:Thm2-construction}
    \Sigma^\star=\widehat V \Phi(\tau, \gamma^\star, \widehat{\lambda}) \widehat V^\top,\quad  X^\star=(\Sigma^\star)^{-1},
    \end{eqnarray} 
    where 
$\widehat V$ and $\widehat \lambda$ are defined as in Remark~\ref{Rem:reg-Spec-esti} and
    $ 
     \Phi(\tau, \gamma^\star, \widehat{\lambda})\triangleq \mathrm{diag}(\varphi(\tau, \gamma^\star, \widehat{\lambda}_1), \ldots ,\varphi(\tau, \gamma^\star, \widehat{\lambda}_p))$,

    and $\gamma^\star$ is the unique non-negative root of the equation $\sum_{i=1}^p d(\varphi(\tau, \gamma^\star, \widehat{\lambda}_i), \widehat{\lambda}_i)- \rho=0$.

\label{prop:equivalence-Mat-Vec}
    Let Assumptions~\ref{ass:regularity-nominal}-\ref{ass:Spectral-divergence} hold. Then problem~\eqref{prob:P-Mat} is equivalent to~\eqref{prob:vector} in the following sense:
    \begin{enumerate}[label=(\roman*)]
        \item\label{prop:equivalence-Mat-Vec-1} If $s^\star$ solves~\eqref{prob:vector}, then $\widehat{V}\mathrm{diag}(s^\star)\widehat{V}^\top$ solves~\eqref{prob:P-Mat}.
        \item\label{prop:equivalence-Mat-Vec-2} If $\Sigma^\star$ solves~\eqref{prob:P-Mat}, then the vector of its eigenvalues $\lambda(\Sigma^\star)$ solves~\eqref{prob:vector}.
    \end{enumerate}

