\label{prop:pro-of-varphi}
If Assumptions~\ref{ass:regularity-nominal}-\ref{ass:Spectral-divergence} hold, then it follows that
\begin{enumerate}[label = (\roman*)]
    \item Let $\varphi_{\tau, b}(\gamma) \triangleq \varphi(\tau, \gamma, b)$. If $\tau>0$, $b>0$, then for any $\gamma \geq 0$:
    \begin{align*}
        \left\{\begin{matrix}
            b< \varphi_{\tau, b}(\gamma)\leq 1/\sqrt{\tau},\;\;\text{for}\;\;b< 1/\sqrt{\tau},\\
            1/\sqrt{\tau}\leq \varphi_{\tau, b}(\gamma)< b,\;\;\text{for}\;\;b> 1/\sqrt{\tau},\\
            \varphi_{\tau, b}(\gamma) = 1/\sqrt{\tau},\;\;\text{for}\;\;b= 1/\sqrt{\tau},
        \end{matrix}\right.
    \end{align*}

    \item If $\tau>0$ and $b\geq0$, then $\varphi_{\tau, b}(\gamma)$ is continuous, strictly monotonic and differentiable on $\mathbb{R}_{+}$. Specifically, $\varphi_{\tau,b}(\cdot)$ is strictly increasing if $b>1/\sqrt{\tau}$ and strictly decreasing if $b<1/\sqrt{\tau}$,
    \item If $\tau>0$ and $b\geq0$, then $\varphi_{\tau,b}(0) = 1/\sqrt{\tau}$ and $\lim_{\gamma\to\infty} \varphi_{\tau,b}(\gamma) = b$,
    \item If $\tau>0$ and $\gamma\geq0$, then $\phi(b)\triangleq \frac{\varphi(\tau,\gamma,b)}{b}$ is non-increasing on $b$.
\end{enumerate}

To see how the estimator can be parameterized by the radius $\rho$ when $\rho$ varies in $(0, \rho_{\max}]$, we note that $\gamma^\star$ can be viewed as a function of $\rho$ in the sense of 
\begin{align}\label{def-gamma-opt}
    \gamma_{\widehat\lambda}^\star(\rho) \triangleq \text{the unique solution $\gamma^\star\geq 0$ of the equation } F_{\widehat\lambda}(\gamma^\star) = \rho,
\end{align}
where $F_{\widehat\lambda}$ is defined as in Proposition~\ref{prop:property-of-F}. By Proposition~\ref{prop:property-of-F}, $\gamma_{\widehat\lambda}^\star(\rho_{\max}) = 0$, $\lim_{\rho\downarrow 0}\gamma_{\widehat\lambda}^\star(\rho) = \infty$, and $\gamma_{\widehat\lambda}^\star(\rho)$ is  strictly decreasing in $\rho$.
Moreover, it follows by \eqref{eq:Thm2-construction} in Theorem~\ref{thm:close-form-dro} that
\begin{align}\label{eq:construct-Sigma-opt}
    \Sigma^\star(\tau,  \rho)=\widehat{V}\Phi(\tau, \gamma_{\widehat\lambda}^\star( \rho), \widehat{\lambda})\widehat{V}^\top\triangleq\widehat V \mathrm{diag}(\varphi(\tau, \gamma_{\widehat\lambda}^\star( \rho), \widehat{\lambda}_1), \ldots ,\varphi(\tau, \gamma_{\widehat\lambda}^\star( \rho), \widehat{\lambda}_p))\widehat V^\top,  \rho\in (0,  \rho_{\max}].
\end{align}
Here we write $\Sigma^\star(\tau,\rho)$ to emphasize its dependence on $\tau$ and $\rho$. Consequently, we can show that $\Sigma^\star(\tau,  \rho)$ is a nonlinear shrinkage estimator, and the spectral bias of the estimator is corrected. The next theorem states these.

\begin{align}\label{def-gamma-opt}
    \gamma_{\widehat\lambda}^\star(\rho) \triangleq \text{the unique solution $\gamma^\star\geq 0$ of the equation } F_{\widehat\lambda}(\gamma^\star) = \rho,
\end{align}

