   Define the Lagrangian function of problem~\eqref{prob:vector}  
    \[
        L(\gamma, s) = \sum_{i=1}^p \log s_i - \frac{1}{2}\tau\sum_{i=1}^p s_i^2 -\gamma \left(\sum_{i=1}^p d(s_i,\widehat{\lambda}_i)- \rho\right).
    \]
  By~\citet[Theorem 28.3]{ref:Rockafellar1970},~\eqref{prob:vector} can be represented as
    \begin{align}
        \max_{s\in\mathbb{R}_+^p} \min_{\gamma \geq 0} L(\gamma, s) = \min_{\gamma \geq 0}\max_{s\in\mathbb{R}_+^p}  L(\gamma, s), \label{prob:vector-Lagrangian}
    \end{align}
    where the left-hand side is the primal problem and the right-hand side is the Lagrange dual problem.
    Equation~\eqref{prob:vector-Lagrangian} means that strong duality holds.  
Let $\gamma^\star$ be an optimal solution of the dual problem. Then
    \[
        \max_{s\in\mathbb{R}_+^p} L(\gamma^\star, s)= \gamma^\star \rho + \sum_{i=1}^p\max_{s_i>0}\left\{ \log s_i-\frac{1}{2}\tau s_i^2 - \gamma^\star d(s_i,\widehat{\lambda}_i)\right\}.
    \]
The problem above is decomposable, which means that it can be solved by solving the following univariate maximization problem 
    \begin{align}
        \max_{s_i>0}\;\; \log s_i-\frac{1}{2}\tau s_i^2 - \gamma^\star d(s_i,\widehat{\lambda}_i), \label{prob:univariate-prob}
    \end{align}
    for $i=1, \ldots ,p$.
    The first-order optimality condition of the problem above  
    \begin{align}
        \frac{1}{s_i}-\tau s_i-\gamma^\star\frac{\partial d}{\partial s_i}(s_i,\widehat{\lambda}_i)=0. \label{eq:first-order-optimality}
    \end{align}
    By Proposition~\ref{prop:unique-varphi},~\eqref{eq:first-order-optimality} always admits a unique strictly positive solution for 
    any 
    fixed $\tau>0,\gamma^\star\geq 0$ and $\widehat{\lambda}_i\geq 0$. Exploiting the notation defined in~\eqref{eq:def-varphi}, the optimal solution to~\eqref{prob:univariate-prob} is $s_i^\star=\varphi(\tau, \gamma^\star, \widehat{\lambda}_i)$.

    Next, we prove that $\sum_{i=1}^p d(\varphi(\tau, \gamma^\star, \widehat{\lambda}_i), \widehat{\lambda}_i)- \rho=0$. If $\rho = \rho_{\max}$, then $\gamma^\star=0$ solves the equation since $\varphi(\tau,0,\widehat\lambda_i)=\sqrt{\frac{1}{\tau}}$ and thus $\sum_{i=1}^p d(\varphi(\tau, \gamma^\star, \widehat{\lambda}_i), \widehat{\lambda}_i) = \rho_{\max}$ by definition of $\rho_{\max}$. Let $\rho\in(0,\rho_{\max})$.    It suffices to prove $\gamma^\star>0$ since the complementarity condition in the KKT conditions will ensure the equality and the feasibility. Assume for the sake of a contradiction that $\gamma^\star=0$. Then by~\eqref{eq:first-order-optimality}, $\left(0, \left(\sqrt{\frac{1}{\tau}}, \ldots ,\sqrt{\frac{1}{\tau}}\right)^\top\right)$ is a saddle point of~\eqref{prob:vector-Lagrangian}, which contradicts the assumption that $\sum_{i=1}^p d\left(\sqrt{\frac{1}{\tau}},\widehat{\lambda}_i\right) = \rho_{\max} >  \rho$. 
    This shows that $\gamma^\star>0$ as desired. Moreover, Lemma~\ref{lemma:property-of-F} below ensures the uniqueness of $\gamma^\star$, which completes the proof.

\label{lemma:property-of-F}
    Let the function $
    F_{\widehat\lambda}:\mathbb{R}_+\to \mathbb{R}$ be defined by 
    \begin{eqnarray} 
    F_{\widehat\lambda}(\gamma)=\sum_{i=1}^p d(\varphi(\tau, \gamma, \widehat{\lambda}_i), \widehat{\lambda}_i).
    \end{eqnarray} 
    If Assumptions~\ref{ass:regularity-nominal}-\ref{ass:regularity} hold, then the function $F_{\widehat\lambda}$ is strictly decreasing over $\mathbb{R}_+$. If Assumption~\ref{ass:reg-radius} holds in addition, then 
    \begin{eqnarray} 
    F_{\widehat\lambda}(0) =  \rho_{\max} \geq  \rho \quad  \text{and}\quad  \lim_{\gamma\to\infty} F_{\widehat\lambda}(\gamma) = 0 \leq  \rho.
    \end{eqnarray}

\label{lemma:monoton-d}
    If Assumptions~\ref{ass:convex-divergence} and~\ref{ass:Spectral-divergence} hold, then we have 
    \begin{enumerate}[label=(\roman*)]
        \item if $a_1 < a_2 < b$, then $d(a_1,b) > d(a_2,b)$,
        \item if $a_1 > a_2 > b$, then $d(a_1,b) > d(a_2,b)$.
    \end{enumerate}

The conclusion on the eigenvalue mappings follows directly from 
the definition of $\varphi$ (see equation~\eqref{eq:def-varphi}) by
    substituting the specific forms of generators $d$ into the equation.
    We omit the details of the calculations.

In what follows, we derive the upper bound,  denoted by $\overline{\gamma}$, of the dual variables $\gamma^\star$.
By Proposition~\ref{prop:property-of-F}, $\overline{\gamma}\geq \gamma^\star$ if and only if $F_{\widehat\lambda}(\overline{\gamma})\leq  \rho$, i.e., 
    \begin{eqnarray} 
        \sum_{i=1}^p d(\varphi(\tau, \overline{\gamma}, \widehat\lambda_i), \widehat\lambda_i) \leq  \rho.
    \end{eqnarray}
    It suffices to choose $\overline{\gamma}$ such that 
    \begin{align}\label{ineq:d<=eps/p}
        d(\varphi(\tau, \overline{\gamma}, \widehat\lambda_i), \widehat\lambda_i) \leq \frac{ \rho}{p},\;\; \text{for}\;  i=1,...,p.
    \end{align}
    To ease the exposition, let
    $a^\star \triangleq \varphi(\tau,\gamma,b)$. We also recall that by Theorem~\ref{thm:nonlinear-shrinkage} (i) and (ii)
    \begin{eqnarray} 
    \widehat\lambda_1\leq \varphi(\tau,\gamma,\widehat\lambda_i)\leq \widehat\lambda_p\;\; \forall \gamma>0, 
    \end{eqnarray} 
   for $i=1,...,p$. 

    \underline{Upper bound of Kullback-Leibler divergence}. 
    Substituting $d(a,b) = \frac{1}{2}\left(\frac{a}{b}-1-\log\frac{a}{b}\right)$ into~\eqref{ineq:d<=eps/p}, we obtain 
    \[
        \frac{1}{2}\left(\frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_i)}{\widehat\lambda_i} - 1 - \log\frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_i)}{\widehat\lambda_i}\right)\leq \frac{ \rho}{p},\;\; \text{for}\; i=1,...,p.
    \]
   The inequalities above are guaranteed by 
    \begin{align}\label{ineq:gamma-bar-KL}
        \frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_i)}{\widehat\lambda_i} - 1 \leq \frac{ \rho}{p} \text{ and }  
        -\log\frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_i)}{\widehat\lambda_i} \leq \frac{ \rho}{p},\;\; \text{for} \;  i=1,...,p.
    \end{align}
    By Proposition~\ref{prop:pro-of-varphi}(iv), $\phi(b) \triangleq\frac{\varphi(\tau,\gamma,b)}{b}$ is non-increasing in $b$. Moreover, by Proposition~\ref{prop:pro-of-varphi}(ii) and the assumption that $\widehat\lambda_1<\sqrt{\frac{1}{\tau}} < \widehat\lambda_p$, we have $\frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_1)}{\widehat\lambda_1} > 1$ and $\frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_p)}{\widehat\lambda_p}<1$. 
   Inequalities \eqref{ineq:gamma-bar-KL} are ensured by  
    \begin{align}\label{ineq:gamma-bar-KL-2}
        \frac{\varphi(\tau, \overline{\gamma}, \widehat\lambda_1)}{\widehat\lambda_1} - 1 \leq \frac{ \rho}{p} \text{ and }  
        \log\frac{\widehat\lambda_p}{\varphi(\tau, \overline{\gamma}, \widehat\lambda_p)} \leq \frac{ \rho}{p}.
    \end{align}
    Note that 
    \begin{align*}
        \varphi(\tau, \overline{\gamma}, b) = \frac{2(2+\overline{\gamma})b}{\left(\overline{\gamma}+\sqrt{\overline{\gamma}^2+8\tau(2+\overline{\gamma})b^2}\right)} \leq \frac{(2+\overline{\gamma})b}{\overline{\gamma}}
    \end{align*}
    for $b>0$.
    By taking $\overline{\gamma}\geq \frac{2p}{ \rho}$, we have 
    \[
        \varphi(\tau, \overline{\gamma}, \widehat\lambda_1)\leq \frac{(2+\overline{\gamma})\widehat\lambda_1}{\overline{\gamma}} \leq (\frac{ \rho}{p}+1)\widehat\lambda_1,
    \]
    which gives rise to the first inequality of~\eqref{ineq:gamma-bar-KL-2}. On the other hand, since 
    \begin{align*}
        \varphi(\tau, \overline{\gamma}, b) = \frac{2(2+\overline{\gamma})b}{\left(\overline{\gamma}+\sqrt{\overline{\gamma}^2+8\tau(2+\overline{\gamma})b^2}\right)} \geq \frac{2(2+\overline{\gamma})b}{\overline{\gamma}+\overline{\gamma}+4\tau b^2+2} \geq \frac{\overline{\gamma}b}{,\overline{\gamma}+2\tau b^2+1}
    \end{align*}
    then 
    \[
        \overline{\gamma}\geq \frac{2\tau \widehat\lambda_p^2+1}{e^{ \rho/p}-1}\;\Rightarrow\; \frac{\overline{\gamma}\widehat\lambda_p}{\overline{\gamma}+2\tau \widehat\lambda_p^2+1} \geq \widehat\lambda_p e^{-\frac{ \rho}{p}}
    \]
which gives rise to the second inequality of~\eqref{ineq:gamma-bar-KL-2}. Combining the above results, we obtain an upper bound of $\gamma^\star$: 
    \[
        \overline{\gamma} = \max\left\{\frac{2p}{ \rho},\frac{2\tau \widehat\lambda_p^2+1}{e^{ \rho/p}-1}\right\}.
    \]

    \underline{Upper bound of Wasserstein divergence}. The generator is $d(a,b) = a+b-2\sqrt{ab}$, and the eigenvalue mapping is the unique positive solution $a^\star$ of 
    \[
        \frac{1}{a^\star} - \tau a^\star - \gamma\left(1-\frac{\sqrt{b}}{\sqrt{a^\star}}\right) = 0.
    \]
    Reformulating the equation gives
    \begin{align*}
        d(a^\star,b)=\left(\sqrt{a^\star}-\sqrt{b}\right)^2 = \frac{(1-\tau {a^\star}^2)^2}{\gamma^2 a^\star}.
    \end{align*}
    Then~\eqref{ineq:d<=eps/p} becomes 
    \begin{align*}\label{ineq:gamma-bar-W}
        \frac{(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{\overline{\gamma}^2 \varphi(\tau,\overline{\gamma},\widehat\lambda_i)}\leq \frac{ \rho}{p}\;\Longleftrightarrow\;
        \overline{\gamma}^2 \geq \frac{p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{ \rho\varphi(\tau,\overline{\gamma},\widehat\lambda_i)}
        ,\;\; \text{for}\; i=1,...,p.
    \end{align*}
    Note that 
    \begin{align*}
        \frac{p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{ \rho\varphi(\tau,\overline{\gamma},\widehat\lambda_i)} \leq \frac{p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{ \rho\varphi(\tau,\overline{\gamma},0)} \leq \max\left\{\frac{p}{ \rho \varphi(\tau,\overline{\gamma},0)}, \frac{p(1-\tau \widehat\lambda_p^2)^2}{ \rho \varphi(\tau,\overline{\gamma},0)}\right\},
    \end{align*}
    where the last inequality is by Lemma~\ref{lemma:1-tau-phi} and 
    \[
        \varphi(\tau,\overline{\gamma},0) = \frac{-\overline{\gamma}+\sqrt{\overline{\gamma}^2+4\tau}}{2\tau}.
    \]
    Then it suffices to have 
    \[
        \max\left\{\frac{p}{ \rho \varphi(\tau,\overline{\gamma},0)}, \frac{p(1-\tau \widehat\lambda_p^2)^2}{\rho \varphi(\tau,\overline{\gamma},0)}\right\} \leq \overline{\gamma}^2.
    \]
    Solving the above inequality, we conclude that 
    \[
        \overline{\gamma} = \max\left\{\frac{\eta_1+\sqrt{\eta_1^2+16\eta_1\tau^{2.5}}}{8\tau^2},\frac{\eta_2+\sqrt{\eta_2^2+16\eta_2\tau^{2.5}}}{8\tau^2}\right\}
    \]
    satisfies the inequality, where
    \[
        \eta_1 = \frac{p}{\rho}~~~\text{and}~~~\eta_2 = \frac{p(1-\tau\widehat\lambda_p^2)^2}{\rho}.
    \]

    \underline{Upper bound of symmetrized Stein divergence}. The generator is $d(a,b)=\frac{1}{2}\left(\frac{b}{a}+\frac{a}{b}-2\right)$, and the eigenvalue mapping is the unique positive solution $a^\star$ of 
    \begin{align*}\label{eq:def-SS-solution-mapping}
        \frac{1}{a^\star}-\tau a^\star -\frac{\gamma}{2}\left(-\frac{b}{{a^\star}^2}+\frac{1}{b}\right)=0.
    \end{align*}
    Reordering the terms of the above equation gives 
    \begin{align*}
        d(a^\star,b)=\frac{(a^\star-b)^2}{2a^\star b} = \frac{2a^\star b(1-\tau {a^\star}^2)^2}{\gamma^2(a^\star+b)^2}.
    \end{align*}
    Then~\eqref{ineq:d<=eps/p} becomes 
    \begin{align*}
        \frac{2\widehat\lambda_i\varphi(\tau,\overline{\gamma},\widehat\lambda_i)(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{\overline{\gamma}^2(\varphi(\tau,\overline{\gamma},\widehat\lambda_i)+\widehat\lambda_i)^2} \leq \frac{ \rho}{p} \;\Leftrightarrow \; \overline{\gamma}^2 \geq \frac{2p\widehat\lambda_i\varphi(\tau,\overline{\gamma},\widehat\lambda_i)(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{\rho(\varphi(\tau,\overline{\gamma},\widehat\lambda_i)+\widehat\lambda_i)^2}, 
        \forall i=1,\ldots,p.
    \end{align*}
    Note that 
    \begin{align*}
        \frac{2p\widehat\lambda_i\varphi(\tau,\overline{\gamma},\widehat\lambda_i)(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{\rho(\varphi(\tau,\overline{\gamma},\widehat\lambda_i)+\widehat\lambda_i)^2} \leq 
        \frac{p\widehat\lambda_p^2(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{2 \rho \widehat\lambda_1^4}\leq \max\left\{\frac{p\widehat\lambda_p^2}{2 \rho \widehat\lambda_1^4},\frac{2p\widehat\lambda_p^2(1-\tau \widehat\lambda_p^2)^2}{4 \rho \widehat\lambda_1^4}\right\},
    \end{align*}
    where the last inequality is by Lemma~\ref{lemma:1-tau-phi}.
    So we set
    \[
        \overline{\gamma} \triangleq\sqrt{\max\left\{\frac{p\widehat\lambda_p^2}{2 \rho \widehat\lambda_1^4},\frac{p\widehat\lambda_p^2(1-\tau \widehat\lambda_p^2)^2}{2 \rho \widehat\lambda_1^4}\right\}}.
    \]

    \underline{Upper bound of squared Frobenius divergence}. The generator is $d(a,b)=(a-b)^2$, and the eigenvalue mapping is the unique positive solution $a^\star$ of 
    \begin{align*}\label{eq:def-SF-solution-mapping}
        \frac{1}{a^\star}-\tau a^\star - 2\gamma(a^\star-b) = 0.
    \end{align*}
    Reordering the terms of the above equation gives
    \[
        d(a^\star,b)=(a^\star-b)^2 = \frac{(1-\tau {a^\star}^2)^2}{4\gamma^2{a^\star}^2}.
    \]
    Consequently,~\eqref{ineq:d<=eps/p} reduces to
    \begin{align*}\label{ineq:gamma-bar-W}
        \frac{(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4\overline{\gamma}^2\varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2}
        \leq \frac{ \rho}{p}
        \;\Longleftrightarrow\;
        \overline{\gamma}^2\geq \frac{p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4 \rho\varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2}
        ,\;\; \text{for}\;  i=1,...,p.
    \end{align*}
    Note that
    \begin{align*}
        \frac{p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4 \rho\varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2} \leq \frac{p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4 \rho\varphi(\tau,\overline{\gamma},0)^2} \leq \max\left\{\frac{p}{4 \rho\varphi(\tau,\overline{\gamma},0)^2},\frac{p(1-\tau \widehat\lambda_p^2)^2}{4 \rho\varphi(\tau,\overline{\gamma},0)^2}\right\},
    \end{align*}
    where the last inequality is by Lemma~\ref{lemma:1-tau-phi} and 
    \[
        \varphi(\tau,\overline{\gamma},0) = \sqrt{\frac{1}{\tau+2\overline{\gamma}}}.
    \]
    Let 
    \[
        \max\left\{\frac{p}{4 \rho}(\tau+2\overline{\gamma}),\frac{p(1-\tau \widehat\lambda_p^2)^2}{4 \rho}(\tau+2\overline{\gamma})\right\} \leq \overline{\gamma}^2.
    \]
    We get
    \[
        \overline{\gamma} \geq \max\left\{\frac{p}{4\rho}+\sqrt{\frac{p^2}{16\rho^2}+\tau\frac{p}{4\rho}}, \frac{p(1-\tau\widehat\lambda_p^2)^2}{4\rho}+\sqrt{\frac{p^2(1-\tau\widehat\lambda_p^2)^4}{16\rho^2}+\tau\frac{p(1-\tau\widehat\lambda_p^2)^2}{4\rho}}\right\}.
    \]

    \underline{Upper bound of weighted Frobenius divergence}. The generator is $d(a,b)=\frac{(a-b)^2}{b}$, and the eigenvalue mapping is the unique positive solution $a^\star$ of 
    \begin{align*}
        \frac{1}{a^\star}-\tau a^\star - \frac{2\gamma}{b}(a^\star-b) = 0.
    \end{align*}
    Reordering the terms of the above equation gives
    \[
        d(a^\star,b)=\frac{(a^\star-b)^2}{b} = \frac{b(1-\tau {a^\star}^2)^2}{4\gamma^2{a^\star}^2}.
    \]
    Consequently~\eqref{ineq:d<=eps/p} reduces to
    \begin{align*}
        \frac{\widehat\lambda_i(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4\overline{\gamma}^2\varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2}
        \leq \frac{ \rho}{p}
        \;\Longleftrightarrow\;
        \overline{\gamma}^2\geq \frac{p\widehat\lambda_i(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4 \rho\varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2}
        ,\;\; \text{for}\; i=1,...,p.
    \end{align*}
    Since 
    \begin{align*}
        \frac{p\widehat\lambda_i(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4 \rho\varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2} \leq \frac{p\widehat\lambda_p(1-\tau \varphi(\tau,\overline{\gamma},\widehat\lambda_i)^2)^2}{4 \rho\widehat\lambda_1^2} \leq \max\left\{\frac{p\widehat\lambda_p}{4 \rho\widehat\lambda_1^2},\frac{p\widehat\lambda_p(1-\tau \widehat\lambda_p^2)^2}{4 \rho\widehat\lambda_1^2}\right\},
    \end{align*} where the last inequality is by Lemma~\ref{lemma:1-tau-phi}, then we can set
    \begin{align*}
        \overline{\gamma} \triangleq\sqrt{\max\left\{\frac{p\widehat\lambda_p}{4 \rho\widehat\lambda_1^2},\frac{p\widehat\lambda_p(1-\tau \widehat\lambda_p^2)^2}{4 \rho\widehat\lambda_1^2}\right\}}.
    \end{align*}

The proof  is similar to~\citet[Proposition 7]{ref:yue2024geometric}. In this proof, we write $x^\star_{i,n}=\lambda_i(\Sigma^\star_{n}(\tau, \rho_n))$ and $\widehat{x}_{i,n}=\lambda_i(\widehat\Sigma)$ for $i=1,\ldots,n$ and $n\in \mathbb{N}$. By the strong consistency assumption, $\widehat\Sigma_n$ converges to $\Sigma_0$ almost surely as $n\to\infty$. Now fix a particular realization of the uncertainties, where $\widehat\Sigma_n$ converges to $\Sigma_0$ deterministically. Then it holds that $\lim_{n\to\infty} \widehat{x}_{i,n}=\lambda_i(\Sigma_0)$ for $i=1,\ldots,p$ since the eigenvalue mapping $\lambda_i$ is continuous. On the other hand, by Proposition~\ref{prop:pro-of-varphi}(ii) we know that $0\leq x^\star_{i,n} \leq \max\left\{\sqrt{\frac{1}{\tau}},b\right\}$, i.e., $\{x^\star_{i,n}\}_{n\in\mathbb{N}}$ is bounded. Let $\{x^\star_{i,n_k}\}_{k\in\mathbb{N}}$ be a convergent subsequence of $\{x^\star_{i,n}\}_{n\in\mathbb{N}}$. Then by Assumption~\ref{ass:Spectral-divergence}, it holds that 
\begin{eqnarray} 
\label{eq:prop9-proof-1}
d\left(x^\star_{i,n_k},\widehat{x}_{i,n_k}\right) \leq \sum_{j=1}^p d(x^\star_{j,n_k},\widehat{x}_{j,n_k}) = D\left(\Sigma^\star_n(\tau, \rho_n), \widehat\Sigma_n\right) \leq  \rho_{n_k},\quad \forall k \in\mathbb{N},
\end{eqnarray} 
for $i=1,\ldots,p$. Since $ \rho_{n_k}$ converges to $0$ and $d$ is continuous by Assumption~\ref{ass:Spectral-divergence} (ii), then \eqref{eq:prop9-proof-1} implies that 
\begin{eqnarray}
\label{eq:prop9-proof-2}
    d\left(\lim_{k\to\infty} x^\star_{i,n_k},\lambda_i(\Sigma_0)\right) = d\left(\lim_{k\to\infty} x^\star_{i,n_k},\lim_{k\to\infty} \widehat{x}_{i,n_k}\right) = \lim_{k\to\infty}d\left(x^\star_{i,n_k},\widehat{x}_{i,n_k}\right) = 0.
\end{eqnarray} 
Recall that by Assumption~\ref{ass:Spectral-divergence}, $d$ satisfies the identity of indiscernibles. Thus \eqref{eq:prop9-proof-2} implies that $\lim_{k\to\infty} x^\star_{i,n_k}=\lambda_i(\Sigma_0)$. This shows that every convergent subsequence of the bounded sequence $\{x^\star_{i,n}\}_{n\in\mathbb{N}}$ must have the same limit $\lambda_i(\Sigma_0)$. By~\cite[Exercise 2.5.5]{ref:abbott2015understanding}, it holds that $\lim_{n\to\infty} x^\star_{i,n} = \lambda_i(\Sigma_0)$. The derivation so far applies to every uncertainty realization where $\widehat\Sigma_n$ converges to $\Sigma_0$ deterministically. Since $\widehat\Sigma_n$ converges to $\Sigma_0$ almost surely, we conclude that $x^\star_{i,n}$ converges to $\lambda_i(\Sigma_0)$ almost surely. This implies that 
\begin{align*}
    \mathbb{P}\left(\lim_{n\to\infty} \|\Sigma_n^\star(\tau, \rho_n)-\Sigma_0\|_F=0\right) \;\geq\; &\mathbb{P}\left(\lim_{n\to\infty}\left( \|\Sigma_n^\star(\tau, \rho_n)-\widehat\Sigma_n\|_F+\|\widehat\Sigma_n-\Sigma_0\|_F\right)=0\right)\\
    \;=\; &\mathbb{P}\left(\lim_{n\to\infty}\left(\|x_n^\star-\widehat{x}_n\|_2+\|\widehat\Sigma_n-\Sigma_0\|_F\right)=0\right)\\
    \;\geq \;&\mathbb{P}\left(\lim_{n\to\infty}\left(\|x_n^\star-\lambda(\Sigma_0)\|_2+\|\widehat{x}_n-\lambda(\Sigma_0)\|_2+\|\widehat\Sigma_n-\Sigma_0\|_F\right)=0\right) \\
    \;= \; &1,
\end{align*}
where $x_n^\star$ and $\widehat{x}_n$ are the vectors of $x^\star_{i,n},i=1,\ldots,p$ and $\widehat{x}_{i,n},i=1,\ldots,p$, and $\lambda(\Sigma_0)$ is the eigenvalue vector of $\Sigma_0$. Both inequalities hold because of the triangle inequality. The first equality holds by the fact that $\|\Sigma_n^\star(\tau, \rho_n)-\widehat\Sigma_n\|_F=\|x_n^\star-\widehat{x}_n\|_2$ since $\Sigma_n^\star(\tau, \rho_n)$ and $\widehat\Sigma_n$ share the same eigenvectors. The last equality holds by the fact that $x^\star_n$ converges to $\lambda(\Sigma_0)$ almost surely, $\widehat{x}_n$ converges to $\lambda(\Sigma_0)$ almost surely, and $\widehat\Sigma_n$ converges to $\Sigma_0$ almost surely. This shows that $\Sigma^\star_n(\tau, \rho_n)$ converges to $\Sigma_0$ almost surely and completes the proof.

\label{prop:rate-of-d}
    Let Assumptions~\ref{ass:regularity-nominal}-~\ref{ass:Spectral-divergence} and~\ref{ass:like-frob} hold, and 
    $\tau>0$ and $\lambda\in\mathbb{R}^p_+$ be such that $\lambda_i\neq 1/\sqrt{\tau}$ for some $i=1,\ldots,p$.
    Then
        \begin{eqnarray} 
        \label{eq:Prop14-proof-1}
        \lim_{\gamma\to\infty} \gamma^2  F_{\lambda}(\gamma) = \sum_{i=1}^p C_{\lambda_i, d} \left(\frac{1/\lambda_i-\tau \lambda_i}{d_{\lambda_i}^{\prime\prime}(\lambda_i)} \right)^2,
    \end{eqnarray}
    where $C_{\lambda_i, d}$ is the constant defined as in Assumption~\ref{ass:like-frob}.

    Since~\eqref{def:gamma-n-opt} is a convex quadratic minimization problem of $\gamma$, we can figure out
    the optimal solution 
    \[
        \gamma^\star_n = \frac{2\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n {\nabla_1 D }(\Sigma_0, \widehat \Sigma_n)\right\rangle}{\|\mathbb{E}_n {\nabla_1 D }(\Sigma_0, \widehat \Sigma_n)\|_F^2}.
    \]
    By Assumption~\ref{ass:D'neq0},  
    \begin{eqnarray} 
       \label{eq:Thm4-proof-CNX-2}
        \lim_{n\to\infty} \gamma^\star_n/n = \lim_{n\to\infty} \frac{2n\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n {\nabla_1 D }(\Sigma_0, \widehat \Sigma_n)\right\rangle}{n^2\|\mathbb{E}_n {\nabla_1 D }(\Sigma_0, \widehat \Sigma_n)\|_F^2} = \frac{2C_2}{C_1^2}.
\end{eqnarray} 
    A combination of \eqref{eq:Prop14-proof-1} and \eqref{eq:Thm4-proof-CNX-2} yields
    \begin{align*}
        \lim_{n\to\infty} n^2  \rho_n^\star = \lim_{n\to\infty} (\gamma_n^\star)^2  F_{\lambda}(\gamma_n^\star)\cdot\lim_{n\to\infty} n^2/ (\gamma_n^\star)^2 =  \rho^\star \triangleq \frac{C_1^4}{4C_2^2} \sum_{i=1}^p C_{\lambda_i, d} \left(\frac{1/\lambda_i-\tau \lambda_i}{d_{\lambda_i}^{\prime\prime}(\lambda_i)} \right)^2.
    \end{align*}
    The proof is complete.

\label{prop:KL-frob-like}
    Let $d(a,b)=\frac{1}{2}(\frac{a}{b}-1-\log\frac{a}{b})$ be defined on $\mathbb{R}_{++}\times \mathbb{R}_{++}$. Then for any $b>0$,  
    \begin{eqnarray} 
        \lim_{a\to b} \frac{d(a,b)}{(a-b)^2} = \frac{1}{4b^2}.
    \end{eqnarray}

\label{prop:KL-D'-limit}
    Let 
    \begin{eqnarray} 
    D(\Sigma_1, \Sigma_2) \triangleq \frac{1}{2}\big(\mathrm{Tr}(\Sigma_2^{-1}\Sigma_1)-p+\log\det(\Sigma_2\Sigma_1^{-1})\big)
    \end{eqnarray} 
    be defined on ${\mathbb{S}^p_{++}} \times {\mathbb{S}^p_{++}}$. Then
    \begin{eqnarray} 
    {\nabla_1 D }(\Sigma_1, \Sigma_2) = \frac{1}{2}\left(\Sigma_2^{-1}-\Sigma_1^{-1}\right).
    \end{eqnarray} 
    Under Assumption~\ref{ass:normal-distribution}, 
    \begin{eqnarray} 
    \label{eq:Prop-state-1}
        \lim_{n\to\infty} n\|\mathbb{E}_n[{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\|_F = \frac{p+1}{2}\|\Sigma_0^{-1}\|_F > 0
     \end{eqnarray} 
     and hence
     \begin{eqnarray} 
     \label{eq:Prop-state-2}
        \lim_{n\to\infty} n\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n [{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\right\rangle=\frac{p+1}{2}\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right) > 0.
     \end{eqnarray}

Note that under Assumption~\ref{ass:normal-distribution}, $
(n\widehat \Sigma_n)^{-1}$ follows Inverse-Wishart distribution and thus 
\begin{eqnarray*} 
\mathbb{E}_n[(n\widehat \Sigma_n)^{-1}] = \frac{1}{n-p-1}\Sigma_0^{-1}.
\end{eqnarray*}
Consequently we have 
\begin{eqnarray} 
  \label{eq:Prop16-proof-1}
    \mathbb{E}_n[{\nabla_1 D }(\Sigma_0-\widehat \Sigma_n)] = \frac{1}{2}\mathbb{E}_n [\widehat \Sigma_n^{-1}-\Sigma_0^{-1}] = \frac{p+1}{2(n-p-1)}\Sigma_0^{-1}.
\end{eqnarray} 
A combination of the two equations above yields 
\[
    \lim_{n\to\infty} n\|\mathbb{E}_n[{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\|_F = \lim_{n\to\infty} \frac{n(p+1)}{2(n-p-1)}\|\Sigma_0^{-1}\|_F = \frac{p+1}{2}\|\Sigma_0^{-1}\|_F,
 \]
 which is \eqref{eq:Prop-state-1}.

 Likewise, we can use \eqref{eq:Prop16-proof-1} to establish 
 \eqref{eq:Prop-state-2}, i.e.,
\begin{align*}
    \lim_{n\to\infty} n\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n [{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\right\rangle=\;& \lim_{n\to\infty} \frac{n(p+1)}{2(n-p-1)}\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right) \\=\;& \frac{p+1}{2}\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right) > 0,
\end{align*}
where the last inequality is due to the fact that 
\begin{align*}
    \|\Sigma_0\|_F^2\|\Sigma_0^{-1}\|_F^2 = \left(\sum_{i=1}^p \lambda_i^2\right)\left(\sum_{i=1}^p \frac{1}{\lambda_i^2}\right) > p^2.
\end{align*}
Note that the above inequality never becomes equality because $\lambda_1,\ldots,\lambda_p$ are not identical.

All the assumptions of Theorem~\ref{thm:optimal-eps-limit} are fulfilled and the constants are $C_{b,d}=\frac{1}{4b^2}$, $C_1=\frac{p+1}{2}\|\Sigma_0^{-1}\|_F$ and $C_2=\frac{p+1}{2}\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right)$. So the limit is 
\begin{align*}
    \lim_{n\to\infty} n^2  \rho_n^\star = \frac{C_1^4}{4C_2^2} \sum_{i=1}^p C_{\lambda_i, d} \left(\frac{1/\lambda_i-\tau^\star \lambda_i}{d_{\lambda_i}^{\prime\prime}(\lambda_i)} \right)^2 = \frac{(p+1)^2\|\Sigma_0^{-1}\|_F^4}{16\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right)^2}\sum_{i=1}^p \left(1-\tau^\star {\lambda_i}^2\right)^2.
\end{align*}

Note that 
\begin{align*}
    d(a,b) = a+b-2\sqrt{ab} = (\sqrt{a}-\sqrt{b})^2 = \left(\frac{a-b}{\sqrt{a}+\sqrt{b}}\right)^2.
\end{align*}
So
\begin{align*}
    \lim_{a\to b} \frac{d(a,b)}{(a-b)^2} = \lim_{a\to b} \frac{1}{(\sqrt{a}+\sqrt{b})^2} = \frac{1}{4b}.
\end{align*}
This completes the proof.

\label{prop:W-D'-limit}
    Let \begin{eqnarray} 
    D(\Sigma_1, \Sigma_2) = \mathrm{Tr}(\Sigma_1+\Sigma_2-2(\Sigma_1\Sigma_2)^{1/2})\end{eqnarray} 
    be defined on ${\mathbb{S}^p_{+}} \times {\mathbb{S}^p_{+}}$
    and  ${\nabla_1 D }(\Sigma_1, \Sigma_2) = I - \Sigma_2(\Sigma_1\Sigma_2)^{-1/2}$. Under Assumption~\ref{ass:normal-distribution}, we have 
    \[
        \lim_{n\to\infty} n\|\mathbb{E}_n[{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\|_F = \frac{(p+1)\sqrt{p}}{8}
     \]
     and
     \[
        \lim_{n\to\infty} n\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n [{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\right\rangle=\frac{p+1}{8}\left(\mathrm{Tr}(\Sigma_0^{-1}) - \frac{p}{\|\Sigma_0\|_F^2}\mathrm{Tr}(\Sigma_0)\right)> 0.
     \]

For ${\nabla_1 D }(\Sigma_0, \widehat\Sigma_n) = I - \widehat\Sigma_n(\Sigma_0\widehat\Sigma_n)^{-1/2}$, we have 
\begin{align*}
    \mathbb{E}_n[{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)] = \mathbb{E}_n[I - \widehat\Sigma_n(\Sigma_0\widehat\Sigma_n)^{-1/2}] = \mathbb{E}_n[I-\Sigma_0^{-1}(\Sigma_0\widehat\Sigma_n)^{1/2}].
\end{align*}
The following proof is based on the expansion of $\mathbb{E}_n [(\Sigma_0\widehat\Sigma_n)^{1/2}]$ given in Lemma~\ref{lemma:Wishart-matrix} (iv). For the first limit, we have
\begin{align}
\|\mathbb{E}_n [I - \Sigma_0^{-1}(\Sigma_0\widehat\Sigma_n)^{1/2}]\|_F^2 = \;&\mathrm{Tr}\left((I-\Sigma_0^{-1}\mathbb{E}_n [(\Sigma_0\Sigma_n)^{1/2}])^2\right)\nonumber\\
=\;&\mathrm{Tr}\left(\left(\frac{p+1}{8n}I+\Sigma_0^{-1}\mathbb{E}_n [R(\widehat \Sigma_n)]\right)^2\right)\nonumber\\
=\;&\frac{(p+1)^2p}{64n^2}+o(1/n^2).
\end{align}
Then 
\begin{align*}
    \lim_{n\to\infty} n\|\mathbb{E}_n[{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\|_F = \sqrt{\lim_{n\to\infty} n^2\|\mathbb{E}_n[{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\|_F^2} = \frac{(p+1)\sqrt{p}}{8}.
\end{align*}
For the second limit, we have 
\begin{align}
    &\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n [I - \Sigma_0^{-1}(\Sigma_0\widehat\Sigma_n)^{1/2}]\right\rangle \nonumber\\=\;& \frac{p+1}{8n}\left(\mathrm{Tr}(\Sigma_0^{-1}) - \frac{p}{\|\Sigma_0\|_F^2}\mathrm{Tr}(\Sigma_0)\right) + \left\langle\Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n [R(\widehat\Sigma_n)]\right\rangle\nonumber\\
    =\;& \frac{p+1}{8n}\left(\mathrm{Tr}(\Sigma_0^{-1}) - \frac{p}{\|\Sigma_0\|_F^2}\mathrm{Tr}(\Sigma_0)\right) + o (1/n).\
\end{align}
Then 
\begin{align*}
    \lim_{n\to\infty} n\left\langle \Sigma_0^{-1}-\frac{p}{\|\Sigma_0\|_F^2}\Sigma_0, \mathbb{E}_n [{\nabla_1 D }(\Sigma_0, \widehat\Sigma_n)]\right\rangle= \frac{p+1}{8}\left(\mathrm{Tr}(\Sigma_0^{-1}) - \frac{p}{\|\Sigma_0\|_F^2}\mathrm{Tr}(\Sigma_0)\right)> 0,
\end{align*}
where the last inequality is by Lemma~\ref{lemma:was-nonnegative}.

All the assumptions of Theorem~\ref{thm:optimal-eps-limit} are fulfilled and the constants are $C_{b,d}=\frac{1}{4b}$, $C_1=\frac{(p+1)\sqrt{p}}{8}$ and $C_2=\frac{p+1}{8}\left(\mathrm{Tr}(\Sigma_0^{-1}) - \frac{p}{\|\Sigma_0\|_F^2}\mathrm{Tr}(\Sigma_0)\right)$. So the limit is 
\begin{align*}
    \lim_{n\to\infty} n^2  \rho_n^\star = \frac{C_1^4}{4C_2^2} \sum_{i=1}^p C_{\lambda_i, d} \left(\frac{1/\lambda_i-\tau^\star \lambda_i}{d_{\lambda_i}^{\prime\prime}(\lambda_i)} \right)^2 = \frac{(p+1)^2p^2}{256\left(\mathrm{Tr}(\Sigma_0^{-1}) - \frac{p}{\|\Sigma_0\|_F^2}\mathrm{Tr}(\Sigma_0)\right)^2}\sum_{i=1}^p \frac{(1-\tau^\star \lambda_i^2)^2}{\lambda_i}.
\end{align*}

 Let $S\sim \mathcal W_p(n, \Sigma)$ be a random matrix following Wishart distribution and $A$ be a constant symmetric matrix, then by~\citet[Theorem 3.3.15 (ii)]{ref:gupta2018matrix}, $\mathbb{E}_n [SAS]=n\Sigma A \Sigma+n\mathrm{Tr}(\Sigma A)\Sigma+n^2 \Sigma A \Sigma$. By the fact that $n\widehat\Sigma_n\sim \mathcal W_p(n, \Sigma_0)$, we prove the following results.

Part (i). $\mathbb{E}_n [\widehat \Sigma_n^2] = \frac{1}{n^2}\mathbb{E}_n [(n\widehat\Sigma_n)^2] = \frac{1}{n^2}(n\Sigma_0^2+n\mathrm{Tr}(\Sigma_0)\Sigma_0+n^2\Sigma_0^2)=\frac{1}{n}\Sigma_0^2+\frac{1}{n}\mathrm{Tr}(\Sigma_0)\Sigma_0+\Sigma_0^2$.

  Part (ii). 
 \begin{align*}
     \mathbb{E}_n [\widehat \Sigma_n \Sigma_0^{-1} \widehat \Sigma_n] =\;& \frac{1}{n^2} \mathbb{E}_n [n \widehat \Sigma_n \Sigma_0^{-1} n \widehat \Sigma_n]\\ =\;& \frac{1}{n^2}(n\Sigma_0\Sigma_0^{-1}\Sigma_0+n\mathrm{Tr}(\Sigma_0\Sigma_0^{-1})\Sigma_0+n^2\Sigma_0\Sigma_0^{-1}\Sigma_0)\\
     =\;& \frac{1}{n^2}(n\Sigma_0+np\Sigma_0+n^2\Sigma_0)
     \\=\;&\frac{1+p+n}{n}\Sigma_0.
 \end{align*}


   Part (iii). 
 \begin{align*}
     \mathbb{E}_n [\|\Sigma_0-\widehat\Sigma_n\|_F^2] = \;&\mathbb{E}_n \left[\mathrm{Tr}\left((\widehat\Sigma_n-\Sigma_0)^2\right)\right]\\=\;&\mathbb{E}_n [\mathrm{Tr}(\Sigma_0^2)+\mathrm{Tr}(\widehat \Sigma_n^2)-2\mathrm{Tr}(\Sigma_0\widehat\Sigma_n)] 
     \\=\;& \mathrm{Tr}(\Sigma_0^2) +\mathrm{Tr}(\mathbb{E}_n[\widehat\Sigma_n^2]) - \frac{2}{n}\mathrm{Tr}(\Sigma_0\mathbb{E}_n[n\widehat\Sigma_n])\\
     =\;& \mathrm{Tr}\left(\frac{1}{n}\Sigma_0^2+\frac{1}{n}\mathrm{Tr}(\Sigma_0)\Sigma_0+\Sigma_0^2\right)-\mathrm{Tr}(\Sigma_0^2)
     \\=\;& \frac{1}{n}(\mathrm{Tr}(\Sigma_0^2)+\mathrm{Tr}(\Sigma_0)^2).
 \end{align*}

  Part (iv). Define matrix-valued function $f(X) = (\Sigma_0 X)^{\frac{1}{2}}$. Taylor's expansion (in the Fr\'echet differentiable sense) at $X = \Sigma_0$ gives
 \begin{align*}
     f(X) = \Sigma_0 + \frac{1}{2}(X-\Sigma_0) - \frac{1}{8}(X-\Sigma_0)\Sigma_0^{-1}(X-\Sigma_0) + R(X),
 \end{align*}
 where $\|R(X)\|_F=o(\|\Sigma_0-\widehat\Sigma_n\|_F^2)$.
 Evaluating $\mathbb{E}_n [f(X)]$ at $X=\widehat \Sigma_n$ gives
 \begin{align*}
     \mathbb{E}_n [(\Sigma_0\widehat \Sigma_n)^{\frac{1}{2}}] = \mathbb{E}_n [f(\widehat\Sigma_n)] = \Sigma_0 - \frac{1}{8}\mathbb{E}_n \left[(\widehat\Sigma_n-\Sigma_0)\Sigma_0^{-1}(\widehat\Sigma_n-\Sigma_0)\right] + \mathbb{E}_n [R(\widehat\Sigma_n)].
 \end{align*}
 By Part (ii), we have
 $
     \mathbb{E}_n \left[(\widehat\Sigma_n-\Sigma_0)\Sigma_0^{-1}(\widehat\Sigma_n-\Sigma_0)\right] =\mathbb{E}_n[\widehat\Sigma_n \Sigma_0^{-1}\widehat \Sigma_n- 2\widehat\Sigma_n+\Sigma_0] = \frac{p+1}{n}\Sigma_0
 $.
 Then 
 \begin{align*}
     \mathbb{E}_n [(\Sigma_0\widehat \Sigma_n)^{1/2}] = \Sigma_0 - \frac{p+1}{8n}\Sigma_0 + \mathbb{E}_n [R(\widehat\Sigma_n)],
 \end{align*}
 where 
 \begin{align*}
     \|\mathbb{E}_n [R(\widehat\Sigma_n)]\|_F\leq \mathbb{E}_n [\|R(\widehat\Sigma_n)\|_F]=\mathbb{E}_n [o(\|\Sigma_0-\widehat\Sigma_n\|_F^2)]=o(\mathbb{E}_n [\|\Sigma_0-\widehat\Sigma_n\|_F^2]) = o(1/n).
 \end{align*}
 This completes the proof.

All the assumptions of Theorem~\ref{thm:optimal-eps-limit} are fulfilled and the constants are $C_{b,d}=\frac{1}{2b^2}$, $C_1=\frac{p+1}{2}\|\Sigma_0^{-1}\|_F$ and $C_2=\frac{p+1}{2}\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right)$. So the limit is 
\begin{align*}
    \lim_{n\to\infty} n^2  \rho_n^\star = \frac{C_1^4}{4C_2^2} \sum_{i=1}^p C_{\lambda_i, d} \left(\frac{1/\lambda_i-\tau^\star \lambda_i}{d_{\lambda_i}^{\prime\prime}(\lambda_i)} \right)^2 = \frac{(p+1)^2\|\Sigma_0^{-1}\|_F^4}{32\left(\|\Sigma_0^{-1}\|_F^2-\frac{p^2}{\|\Sigma_0\|_F^2}\right)^2}\sum_{i=1}^p \left(1-\tau^\star {\lambda_i}^2\right)^2.
\end{align*}
